We will restrict attention to projected models where  
\begin{equation}\label{eq:losslessPi}
\text{there are a finite number of orbits }
\orbit_{\theta} \text{ such that }
\Pi(\orbit_{\theta}) \equiv
\Pi(\orbit_{\theta_*}), \text{ for generic } \theta_* \in \R^d.
\end{equation}

symmetric moment tensors
\begin{equation}\label{eq:Tk}
T_k(\theta)=\int_\G (g \cdot \theta)^{\otimes k}\,\der \Lambda(g)
\in \R^{d \times \ldots \times d}
\end{equation}
where $T_k(\theta)$ is a tensor of order $k$. The entries of
$T_k(\theta)$ are
the $k^\text{th}$-order mixed moments of the distribution of Gaussian
mixture centers $g \cdot \theta$.

\begin{equation}\label{eq:sk}
s_k(\theta)=\frac{1}{2(k!)}\|T_k(\theta)-T_k(\theta_*)\|_\HS^2.
\end{equation}

\begin{equation}\label{eq:tildesk}
\ts_k(\theta)=\frac{1}{2(k!)}\|\tT_k(\theta)-\tT_k(\theta_*)\|_\HS^2.
\end{equation}

\begin{equation}\label{eq:dk}
d_0=\max_{\theta \in \R^d} \dim(\orbit_\theta), \qquad
d_k=\trdeg \cR_{\leq k}^\G-\trdeg \cR_{\leq k-1}^\G \text{ for } k=1,\ldots,K
\end{equation}

