\end{equation}
where $\langle l,m;l',m'|l'',m'' \rangle \in \R$ is the Clebsch-Gordan
coefficient.

Turning to the forms of $s_k(\theta)$ that define the moment optimization
(\ref{eq:momentoptunprojected}), write $\theta_* \in \R^d$ for the true
coefficients in the above real basis $\{h_{lsm}\}$. Let
\begin{equation}\label{eq:uls}
u^{(ls)}(\theta)=(u_m^{(ls)}(\theta):m=-l,\ldots,l) \in \C^{2l+1}
\end{equation}
be the components of the \emph{complex} coefficients $u=\hat{V}^*\theta$
for the frequency pair $(l,s)$, and define analogously to (\ref{eq:Bl})
\begin{equation}\label{eq:Bls}
B_{(l,s),(l',s'),(l'',s'')}(\theta)=
\mathop{\sum_{m=-l}^l \sum_{m'=-l'}^{l'} \sum_{m''=-l''}^{l''}}_{m''=m+m'}
\langle l,m;l',m'|l'',m'' \rangle
\overline{u_m^{(ls)}(\theta)u_{m'}^{(l's')}(\theta)}
u_{m''}^{(l''s'')}(\theta).
\end{equation}
